<script setup lang="ts">
import {onMounted,ref} from 'vue';import {settingsApi,type SettingSection} from '@/lib/api';import Card from '@/components/ui/Card.vue';import Button from '@/components/ui/Button.vue';import Input from '@/components/ui/Input.vue';import Badge from '@/components/ui/Badge.vue';import {useToast} from '@/composables/useToast';const title=ref('');const sources=ref<Record<string,unknown>>({});const {toast}=useToast();const searching=ref(false);const results=ref<Record<string,unknown>[]>([]);onMounted(async()=>sources.value=await settingsApi.getSection('sources'));async function search(){if(!title.value.trim())return;searching.value=true;try{const active=Object.entries(sources.value).filter(([,v])=>v===true).map(([k])=>k);if(active.length===0){toast('请先在「双源」设置中启用搜索源','info');results.value=[]}else toast('当前后端未提供手动搜索 API；请使用订阅同步触发发现流程','info')}finally{searching.value=false}}
</script>
<template><div class="space-y-5"><Card class="p-5 sm:p-7"><h2 class="text-xl font-semibold">全网找源，一键转存</h2><p class="mt-1 text-sm text-muted">按已配置搜索源检查状态并触发搜索</p><form class="mt-5 flex flex-col gap-2 sm:flex-row" @submit.prevent="search"><Input v-model="title" class="min-h-[52px] flex-1" placeholder="输入影视名称"/><Button class="min-h-[52px]" :disabled="searching">{{searching?'检索中…':'搜索全部来源'}}</Button></form></Card><div class="grid gap-4 lg:grid-cols-3"><Card class="p-4 lg:col-span-2"><h3 class="mb-3 font-semibold">搜索结果</h3><div v-if="!results.length" class="py-8 text-center text-sm text-muted">输入标题后搜索；当前 P4 服务未暴露搜索接口，来源运行配置如下。</div><pre v-else class="overflow-auto text-xs">{{JSON.stringify(results,null,2)}}</pre></Card><Card class="p-4"><h3 class="mb-3 font-semibold">来源配置</h3><div v-for="[key,value] in Object.entries(sources)" :key="key" class="flex min-h-11 items-center justify-between border-t border-border text-sm"><span>{{key}}</span><Badge :tone="value?'good':'muted'">{{value?'启用':'配置项'}}</Badge></div><RouterLink to="/radar" class="mt-3 inline-flex min-h-[44px] items-center text-sm text-primary">前往双源雷达 →</RouterLink></Card></div></div></template>